// 추천 공모전: 실제 접수 중인 공모전 + 접수 예정 공모전
// 2026-10-02 기준 위비티(wevity.com)에서 확인한 정보이며, 2026-10-04에 기업·정부기관 주최
// 공모전 18건(id 17~34, 마감 2026-10-23 ~ 2027-03-31)을, 2026-10-06에 위비티 '접수예정'
// 공모전 7건(id 35~41, 접수 시작 2026-10-10 ~ 11-09)을 추가했습니다.
// 2026-10-11에는 콘테스트코리아(contestkorea.com)의 부문별 목록(10개 대분류)에서 접수 중·접수 예정
// 공모전 310건(id 42~352, 마감 2026-10 ~ 2027-01)을 추가했습니다. 공모전은 기간이 지나면 마감되므로
// 주기적으로 최신 정보로 갱신이 필요합니다. 링크는 각 공모전의 상세 정보 페이지이고,
// image는 위비티에 게시된 공모전 포스터 이미지를 내려받아 public/contest/에 둔 것입니다.
// 콘테스트코리아 분은 각 공고 페이지의 대표 이미지를 public/contest/ck/에 내려받아 두었습니다.
// 콘테스트코리아 데이터의 description·applySteps는 목록 메타데이터(주최·대상·접수 기간)로
// 조립한 요약 문장이므로, 상금·주제 범위·제출 양식 등 세부는 반드시 링크 공고문에서 확인해야 합니다.
// startDate는 접수 시작일(YYYY-MM-DD)이며, 아직 접수가 시작되지 않은 공모전(접수 예정)을
// 가리는 데 쓰입니다. startDate가 오늘보다 뒤면 '곧 시작되는 공모전' 박스에만 노출합니다.
// matchReason(추천 이유)은 services/mockAnalysis.js가 입력에 맞게 생성합니다.
// description·applySteps는 공고를 요약해 둔 참고 자료입니다. 세부 일정·상금·제출 양식은
// 반드시 각 공모전 공식 페이지에서 확인해야 합니다.
// ageGroups는 참가 자격(eligibility)을 연령 기준으로 분류해 둔 값입니다 —
// 'teen'(청소년·미성년 참여 가능), 'adult'(성인 참여 가능)를 나열하며 둘 다 있으면
// 누구나 참여 가능이라는 뜻입니다. 탐색 화면의 연령 필터가 이 값을 사용합니다.
